<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{$company->name}} Interview Experiences</title><style>
*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,sans-serif;background:#f4f8fd;color:#102445}.hero{background:linear-gradient(130deg,#0a1a35,#23538b);color:white;padding:60px 20px}.wrap{width:min(1120px,calc(100% - 32px));margin:auto}.hero h1{font-size:46px;margin:12px 0}.badge{display:inline-block;background:#dbeafe;color:#1757b5;padding:7px 12px;border-radius:20px;font-weight:800;font-size:12px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:22px}.btn{display:inline-flex;align-items:center;min-height:44px;padding:0 16px;border-radius:9px;background:#2873f4;color:white;text-decoration:none;font-weight:800;border:0}.btn.alt{background:white;color:#154a8d}.content{display:grid;grid-template-columns:1fr 300px;gap:24px;padding:34px 0 70px}.panel,.card{background:white;border:1px solid #d7e3f2;border-radius:16px;padding:22px}.filters{display:grid;grid-template-columns:1fr 1fr 1fr auto;gap:9px}.filters select,.filters input,.filters button{height:44px;border:1px solid #c8d7e9;border-radius:9px;padding:0 12px}.filters button{background:#286cf0;color:#fff;font-weight:800}.card{margin-top:15px}.card h3{margin:10px 0}.meta{color:#687b95;font-size:14px}.rounds{display:flex;gap:7px;flex-wrap:wrap;margin:14px 0}.rounds span{padding:7px 10px;border-radius:18px;background:#ecf4ff;color:#1a5bb7;font-size:12px}.side h3{margin-top:0}.topic{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid #edf1f7}.salary{padding:9px 0;border-bottom:1px solid #edf1f7}.empty{text-align:center;padding:50px 22px}.pagination{display:flex;gap:6px;list-style:none}.page-link{padding:8px 11px;border:1px solid #ccd9ea;border-radius:7px;text-decoration:none}@media(max-width:850px){.content{grid-template-columns:1fr}.filters{grid-template-columns:1fr}}
</style></head><body><section class="hero"><div class="wrap"><span class="badge">{{str_replace('_',' ',strtoupper($company->tier))}}</span><h1>{{$company->name}}</h1><p>{{$company->industry}} · {{$company->country}}</p><div class="actions"><a class="btn" href="{{route('company.experiences.create',['company'=>$company->id])}}">Share your experience</a><a class="btn alt" href="{{route('company.experiences.compare',['companies'=>[$company->id]])}}">Compare</a></div></div></section><main class="wrap content"><section><div class="panel"><form class="filters"><select name="role"><option value="">All roles</option>@foreach($roles as $role)<option value="{{$role->id}}" @selected(request('role')==$role->id)>{{$role->role_name}}{{$role->experience_level?' · '.$role->experience_level:''}}</option>@endforeach</select><input name="level" value="{{request('level')}}" placeholder="Experience level"><input name="location" value="{{request('location')}}" placeholder="Location"><button>Filter</button></form></div>@forelse($experiences as $item)<article class="card"><div class="meta">{{$item->role?->role_name??'Role not specified'}} · {{$item->location}} · {{ucwords(str_replace('_',' ',$item->experience_level))}}</div><h3>{{$item->total_rounds}} rounds · {{ucfirst(str_replace('_',' ',$item->difficulty))}} difficulty</h3><div class="rounds">@foreach($item->rounds as $round)<span>{{$round->round_number}}. {{$round->round_name}}</span>@endforeach</div><p>{{Str::limit($item->overall_experience,220)}}</p><a href="{{route('company.experiences.experience',[$company->slug,$item->id])}}">Read complete experience →</a></article>@empty<div class="card empty"><h2>No published experiences yet</h2><p>Be the first to share a genuine interview journey for {{$company->name}}. Submissions are reviewed before publication.</p><a class="btn" href="{{route('company.experiences.create',['company'=>$company->id])}}">Share experience</a></div>@endforelse{{$experiences->links()}}</section><aside class="side"><div class="panel"><h3>Preparation topics</h3>@forelse($topicCounts as $topic=>$count)<div class="topic"><span>{{$topic}}</span><b>{{$count}}</b></div>@empty<p class="meta">Topics will appear from verified experiences.</p>@endforelse</div><div class="panel" style="margin-top:18px"><h3>Verified compensation</h3>@forelse($packages as $package)<div class="salary"><b>{{$package->currency}} {{number_format($package->total_compensation??$package->base_salary)}}</b><div class="meta">{{$package->role?->role_name}} · {{$package->location}}</div></div>@empty<p class="meta">No verified salary reports yet.</p>@endforelse</div></aside></main></body></html>
